<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import{ArrowLeft,Briefcase,Building2,Calendar,Edit,Mail,MapPin,Phone,Trash2,User}from'@lucide/vue';import AppLayout from '@/Layouts/AppLayout.vue';const p=defineProps<{client:any,jobs:any[]}>();const remove=()=>confirm('Hapus client ini?')&&router.delete(`/dashboard/clients/${p.client.id}`);const date=(x:any)=>x?new Date(x).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'-';</script>
<template><Head :title="client.name"/><AppLayout><main class="mx-auto max-w-5xl space-y-6 p-4"><div class="flex items-center justify-between"><div class="flex items-center gap-4"><Link href="/dashboard/clients" class="grid h-11 w-11 place-items-center rounded-full hover:bg-pink-500/10"><ArrowLeft/></Link><div><div class="flex items-center gap-2"><h1 class="text-2xl font-black">{{client.name}}</h1><span class="rounded bg-pink-500/10 px-2 py-1 text-[10px] font-black text-pink-500">CL-{{String(client.indexNo||0).padStart(4,'0')}}</span></div><p class="text-sm text-slate-500">Profil lengkap dan riwayat berkas client.</p></div></div><div class="flex gap-2"><Link :href="`/dashboard/clients/${client.id}/edit`" class="flex h-10 items-center gap-2 rounded-xl bg-pink-500 px-4 text-sm font-bold text-white"><Edit class="h-4 w-4"/>Edit</Link><button @click="remove" class="grid h-10 w-10 place-items-center rounded-xl bg-red-500/10 text-red-500"><Trash2 class="h-4 w-4"/></button></div></div>
<section class="grid gap-6 md:grid-cols-3"><div class="rounded-[2rem] bg-white p-6 shadow-sm dark:bg-slate-900 md:col-span-2"><h2 class="mb-6 font-black">Informasi Client</h2><div class="grid gap-6 md:grid-cols-2"><div v-for="x in [{i:client.type==='corporate'?Building2:User,l:'Jenis Client',v:client.type==='corporate'?'Badan Hukum':'Perorangan'},{i:Calendar,l:'Tanggal Lahir',v:date(client.birthday)},{i:Phone,l:'Nomor Handphone',v:client.phone||'-'},{i:Mail,l:'Email',v:client.email||'-'},{i:MapPin,l:'Alamat',v:[client.address,client.village,client.district,client.city,client.province].filter(Boolean).join(', ')||'-'}]" class="flex gap-3"><component :is="x.i" class="h-5 w-5 text-pink-500"/><div><p class="text-[10px] font-black uppercase tracking-widest text-slate-400">{{x.l}}</p><p class="mt-1 text-sm font-bold">{{x.v}}</p></div></div></div></div><div class="rounded-[2rem] bg-pink-500 p-6 text-white"><Briefcase class="h-9 w-9 opacity-80"/><p class="mt-8 text-[10px] font-black uppercase tracking-widest text-white/70">Total Berkas</p><p class="text-4xl font-black">{{jobs.length}}</p></div></section>
<section class="overflow-hidden rounded-[2rem] bg-white shadow-sm dark:bg-slate-900"><header class="border-b p-6 dark:border-slate-800"><h2 class="font-black">Riwayat Kerjasama</h2></header><div v-if="!jobs.length" class="py-16 text-center text-sm text-slate-500">Belum ada berkas untuk client ini.</div><Link v-for="j in jobs" :key="j.id" :href="`/dashboard/jobs/${j.jobType}/${j.id}`" class="flex items-center justify-between border-b p-5 last:border-0 hover:bg-slate-50 dark:border-slate-800 dark:hover:bg-slate-800"><div><p class="font-bold">{{j.title}}</p><p class="text-xs text-slate-500">{{j.trackingCode}} · {{date(j.createdAt)}}</p></div><span class="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-black dark:bg-slate-800">{{j.status}}</span></Link></section></main></AppLayout></template>
